<?php
declare(strict_types=1);
require_once __DIR__.'/app/media.php';
$items=[];
$categories=[
    'publication'=>['title'=>'Research Papers','heading'=>'Research papers.','description'=>'Explore AIDA’s research papers, evidence and publications.','empty'=>'Research papers are being prepared.','note'=>'Published research papers will appear here as they become available.'],
    'event'=>['title'=>'Events & Dialogues','heading'=>'Events and dialogues.','description'=>'Discover AIDA’s public discussions, upcoming events and dialogue videos.','empty'=>'New events and dialogues are being prepared.','note'=>'Published events, discussions and videos will appear here as they become available.'],
    'project'=>['title'=>'Projects & Impact','heading'=>'Projects and impact.','description'=>'Explore AIDA’s initiatives, partnerships and work with communities.','empty'=>'Project updates are being prepared.','note'=>'Published initiatives, project updates and outcomes will appear here as they become available.'],
];
$requestedType=$_GET['type']??'';
$selectedType=is_string($requestedType)&&isset($categories[$requestedType])?$requestedType:'';
$page=$categories[$selectedType]??['title'=>'Insights & Resources','heading'=>'Research, ideas and resources.','description'=>'Explore AIDA’s latest insights, publications, projects and public dialogues.','empty'=>'AIDA’s first resources are being prepared.','note'=>'New research, publications and dialogue updates will appear here.'];
try {
    require_once __DIR__ . '/app/bootstrap.php';
    $query="SELECT c.*,u.name author,cm.authors,cm.category,cm.document_date FROM content c JOIN users u ON u.id=c.author_id LEFT JOIN content_metadata cm ON cm.content_id=c.id WHERE c.status='published' AND NOT EXISTS (SELECT 1 FROM content_state t WHERE t.content_id=c.id AND t.deleted_at IS NOT NULL)";
    if ($selectedType) $query.=' AND c.content_type=?';
    $statement=db()->prepare($query.' ORDER BY COALESCE(c.published_at,c.created_at) DESC');
    $statement->execute($selectedType?[$selectedType]:[]);
    $items=$statement->fetchAll();
} catch (Throwable $e) {}
function page_e(string $value): string { return htmlspecialchars($value,ENT_QUOTES,'UTF-8'); }
$labels=['insight'=>'Insight','publication'=>'Publication','project'=>'Project','event'=>'Event','governance'=>'Governance'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=page_e($page['title'])?> | AIDA</title><link rel="icon" type="image/png" href="Logo.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body class="institution-page"><header class="institution-header" id="top"><nav class="nav container" aria-label="Main navigation"><a class="brand" href="index.php" aria-label="AIDA home"><img src="Logo.png" alt="AIDA"></a><button class="menu-toggle" aria-expanded="false" aria-controls="nav-links"><span></span><span></span><span></span><span class="sr-only">Open menu</span></button><div class="nav-links" id="nav-links"><a href="index.php#about">About us</a><a href="index.php#work">Our work</a><a class="active-link" href="insights.php">Insights</a><a href="governance.php">Governance</a><a href="join.php" class="nav-cta">Partner with us <span>↗</span></a></div></nav></header><main><section class="institution-hero"><div class="container"><p class="eyebrow"><span></span> AIDA KNOWLEDGE HUB</p><div class="row align-items-end g-4"><div class="col-lg-8"><h1><?=page_e($page['heading'])?></h1></div><div class="col-lg-4"><p><?=page_e($page['description'])?></p></div></div></div></section><section class="section"><div class="container"><nav class="resource-filters" aria-label="Resource categories"><a href="insights.php" <?=$selectedType===''?'aria-current="page"':''?>>All resources</a><?php foreach($categories as $key=>$category):?><a href="insights.php?type=<?=page_e($key)?>" <?=$selectedType===$key?'aria-current="page"':''?>><?=page_e($category['title'])?></a><?php endforeach;?></nav><div class="resource-grid"><?php if(!$items):?><div class="empty-state"><p class="section-kicker">COMING SOON</p><h2><?=page_e($page['empty'])?></h2><p><?=page_e($page['note'])?></p></div><?php endif;?><?php foreach($items as $item):?><article class="resource-card" id="content-<?=$item['id']?>"><?php if($item['featured_image']):?><img src="<?=page_e(media_url($item['featured_image']))?>" alt=""><?php endif;?><p class="section-kicker"><?=page_e($labels[$item['content_type']]??'Resource')?> · <?=page_e(date('d M Y',strtotime($item['published_at']?:$item['created_at'])))?></p><h2><?=page_e($item['title'])?></h2><p><?=page_e($item['summary'])?></p><?php if($item['body']):?><div class="resource-body"><?=nl2br(page_e($item['body']))?></div><?php endif;?><?php if($item['authors']||$item['category']||$item['document_date']):?><p class="resource-metadata"><?=page_e(implode(' · ',array_filter([$item['authors'],$item['category'],$item['document_date']])))?></p><?php endif;?><div class="resource-actions"><?php foreach(content_extra_documents((int)$item['id']) as $document):?><a href="file.php?id=<?=$document['id']?>" target="_blank" rel="noopener"><?=page_e($document['original_name'])?></a><?php endforeach;?><?php if($item['document_path']):?><a href="<?=page_e(media_url($item['document_path']))?>" target="_blank" rel="noopener">Download document →</a><?php endif;?><?php if($item['video_url']):?><a href="<?=page_e(media_url($item['video_url']))?>" target="_blank" rel="noopener">Watch video →</a><?php endif;?></div></article><?php endforeach;?></div></div></section></main><footer><div class="container footer-inner"><a class="footer-brand" href="index.php"><img src="Logo.png" alt="AIDA"></a><p>Research. Dialogue. Impact.</p><p>© <?=date('Y')?> Africa Innovation &amp; Development Academy.</p><a href="#top">Back to top ↑</a></div></footer><script src="assets/js/main.js"></script></body></html>
